import { randomUUID } from "node:crypto";
import { mkdir, readFile, rm, stat, writeFile } from "node:fs/promises";
import path from "node:path";
import { AppError, type Config } from "@hks/shared";

/** Private object storage for uploaded documents. Keys are generated by the server, never taken from user input. */
export interface ObjectStorage {
  put(key: string, bytes: Uint8Array, contentType: string): Promise<void>;
  get(key: string): Promise<Uint8Array>;
  delete(key: string): Promise<void>;
  exists(key: string): Promise<boolean>;
}

const KEY = /^org\/[0-9a-f-]{36}\/doc\/[0-9a-f-]{36}$/;

/** `org/<organization id>/doc/<random id>` — no filename, no extension, nothing user-controlled. */
export function newStorageKey(organizationId: string): string {
  return `org/${organizationId}/doc/${randomUUID()}`;
}

function assertKey(key: string) {
  if (!KEY.test(key)) throw new AppError("internal", "Invalid storage key");
}

/** Files on local disk, for development and tests. Not served by any web route. */
export class LocalFileStorage implements ObjectStorage {
  private readonly root: string;
  constructor(root: string) {
    this.root = path.resolve(root);
  }

  private file(key: string) {
    assertKey(key);
    const resolved = path.resolve(this.root, key);
    // Defence in depth on top of the key pattern: never leave the storage root.
    if (!resolved.startsWith(this.root + path.sep)) throw new AppError("internal", "Invalid storage key");
    return resolved;
  }

  async put(key: string, bytes: Uint8Array) {
    const file = this.file(key);
    await mkdir(path.dirname(file), { recursive: true, mode: 0o700 });
    await writeFile(file, bytes, { mode: 0o600 });
  }
  async get(key: string) {
    try {
      return new Uint8Array(await readFile(this.file(key)));
    } catch (error) {
      if ((error as NodeJS.ErrnoException).code === "ENOENT") throw new AppError("not_found", "Stored file not found");
      throw error;
    }
  }
  async delete(key: string) {
    await rm(this.file(key), { force: true });
  }
  async exists(key: string) {
    return stat(this.file(key)).then(() => true, () => false);
  }
}

/**
 * Amazon S3 (or an S3-compatible service). NOT YET VERIFIED: no bucket or
 * credentials were available. Objects are written with server-side encryption
 * and the bucket is expected to block all public access.
 */
export class S3Storage implements ObjectStorage {
  private clientPromise: Promise<import("@aws-sdk/client-s3").S3Client> | undefined;
  constructor(private readonly options: { bucket: string; region?: string; endpoint?: string; forcePathStyle?: boolean }) {}

  private async sdk() {
    const s3 = await import("@aws-sdk/client-s3");
    this.clientPromise ??= Promise.resolve(
      new s3.S3Client({ region: this.options.region, endpoint: this.options.endpoint, forcePathStyle: this.options.forcePathStyle }),
    );
    return { s3, client: await this.clientPromise };
  }

  async put(key: string, bytes: Uint8Array, contentType: string) {
    assertKey(key);
    const { s3, client } = await this.sdk();
    await client.send(
      new s3.PutObjectCommand({ Bucket: this.options.bucket, Key: key, Body: bytes, ContentType: contentType, ServerSideEncryption: "AES256" }),
    );
  }
  async get(key: string) {
    assertKey(key);
    const { s3, client } = await this.sdk();
    try {
      const response = await client.send(new s3.GetObjectCommand({ Bucket: this.options.bucket, Key: key }));
      return await response.Body!.transformToByteArray();
    } catch (error) {
      if ((error as { name?: string }).name === "NoSuchKey") throw new AppError("not_found", "Stored file not found");
      throw error;
    }
  }
  async delete(key: string) {
    assertKey(key);
    const { s3, client } = await this.sdk();
    await client.send(new s3.DeleteObjectCommand({ Bucket: this.options.bucket, Key: key }));
  }
  async exists(key: string) {
    assertKey(key);
    const { s3, client } = await this.sdk();
    return client.send(new s3.HeadObjectCommand({ Bucket: this.options.bucket, Key: key })).then(() => true, () => false);
  }
}

export function createStorage(config: Config): ObjectStorage {
  if (config.STORAGE_DRIVER === "s3") {
    return new S3Storage({
      bucket: config.S3_BUCKET!,
      region: config.S3_REGION ?? config.AWS_REGION,
      endpoint: config.S3_ENDPOINT,
      forcePathStyle: config.S3_FORCE_PATH_STYLE,
    });
  }
  return new LocalFileStorage(config.STORAGE_LOCAL_DIR);
}
